export type Locale = 'es' | 'en' | 'de' | 'fr' | 'pt';

export const LOCALES: Locale[] = ['es', 'en', 'de', 'fr', 'pt'];

export const LOCALE_NAMES: Record<Locale, string> = {
  es: 'Español',
  en: 'English',
  de: 'Deutsch',
  fr: 'Français',
  pt: 'Português',
};

// Full language names, used when instructing the AI what language to
// write in (a locale code like "de" is ambiguous to a model; spelling
// it out as "German" is not).
export const LOCALE_FULL_NAME: Record<string, string> = {
  es: 'Spanish',
  en: 'English',
  de: 'German',
  fr: 'French',
  pt: 'Portuguese',
};

