  'home.tagline': 'Tu sistema operativo de aprendizaje adaptativo.',
  'home.signIn': 'Iniciar sesión',
  'home.signUp': 'Crear cuenta',
  'marketing.seoTitle': 'StudyUS | Apréndelo, demuéstralo, consérvalo',
  'marketing.seoDescription': 'StudyUS es un sistema de aprendizaje adaptativo que te ayuda a entender un concepto, practicarlo, demostrar que puedes hacerlo solo, retenerlo y aplicarlo en situaciones nuevas.',
  'marketing.h1': 'No basta con acertar. Domínalo.',
  'marketing.subhead': 'StudyUS es un sistema de aprendizaje adaptativo. Averigua qué necesitas, te guía para aprenderlo y comprueba que de verdad puedes hacerlo: solo, más adelante y en situaciones nuevas.',
  'marketing.navHowItWorks': 'Cómo funciona',
  'marketing.footerTagline': 'Apréndelo. Demuéstralo. Consérvalo.',
  'marketing.section1Title': 'Decide qué necesitas',
  'marketing.section1Body': 'StudyUS lee tu material, lo divide en conceptos y te dice qué trabajar a continuación: nunca tienes que planificar tu propio estudio.',
  'marketing.section2Title': 'No se conforma con una respuesta correcta',
  'marketing.section2Body': 'Acertar es el principio. Después StudyUS comprueba que puedes hacerlo sin ayuda, que lo recuerdas más adelante y que lo usas en algo nuevo.',
  'marketing.section3Title': 'Te muestra dónde estás de verdad',
  'marketing.section3Body': 'En cada concepto ves qué has entendido, qué has demostrado solo, qué has retenido y qué falta por trabajar: con evidencia real, no una nota.',
  'marketing.section4Title': 'Se adapta a ti',
  'marketing.section4Body': 'Lo que practicas, cuándo vuelve un concepto para repaso y qué te pide StudyUS después siguen tu rendimiento real, no un curso fijo igual para todos.',
  'marketing.section5Title': 'Pensado para el colegio real',
  'marketing.section5Body': 'Sigue tu dominio a lo largo del tiempo y llega a los exámenes -- incluidas las evaluaciones del IB para Diploma y MYP -- preparado, no solo familiarizado.',
  'marketing.ctaPrimary': 'Empieza gratis',
  'marketing.ctaSecondary': 'Ver cómo funciona',
  'marketing.faqTitle': 'Preguntas frecuentes',
  'marketing.faq1Q': '¿StudyUS es un chatbot de IA?',
  'marketing.faq1A': 'No. StudyUS es un sistema de aprendizaje estructurado: decide qué necesitas, guía el aprendizaje y verifica que de verdad puedes hacerlo. No es una ventana de chat para hacer preguntas.',
  'marketing.faq2Q': '¿Son solo tarjetas o cuestionarios?',
  'marketing.faq2A': 'No. Las tarjetas prueban el recuerdo de datos sueltos. StudyUS construye la comprensión de un concepto y luego comprueba que puedes hacerlo solo, recordarlo después y aplicarlo en una situación nueva.',
  'marketing.faq3Q': '¿Solo hace un plan de estudio?',
  'marketing.faq3A': 'No. Un plan te dice cuándo estudiar. StudyUS decide qué estudiar, enseña los conceptos y controla si de verdad estás mejorando.',
  'howItWorks.seoTitle': 'Cómo funciona StudyUS | Aprender, practicar, demostrar, retener, transferir',
  'howItWorks.seoDescription': 'El ciclo de aprendizaje de StudyUS: entender un concepto, practicarlo, demostrar que puedes hacerlo solo, retenerlo en el tiempo y transferirlo a situaciones nuevas.',
  'howItWorks.h1': 'Aprender. Practicar. Demostrar. Retener. Transferir.',
  'howItWorks.intro': 'StudyUS no es una app de tarjetas ni un chatbot. Es un ciclo de aprendizaje que se asegura de que entiendes cada concepto y sabes usarlo, no solo reconocerlo.',
  'howItWorks.step1Title': 'Aprender: construir un modelo mental claro',
  'howItWorks.step1Body': 'Cada concepto se explica con claridad y ejemplos reales, para que entiendas la idea en sí, no un atajo para memorizarla.',
  'howItWorks.step2Title': 'Practicar: trabajarlo, con ayuda',
  'howItWorks.step2Body': 'Aplicas el concepto en práctica guiada, con pistas disponibles, hasta que te resulta familiar.',
  'howItWorks.step3Title': 'Demostrar: hacerlo por tu cuenta',
  'howItWorks.step3Body': 'StudyUS comprueba que puedes hacerlo solo -- sin pistas -- antes de dar el concepto por tuyo.',
  'howItWorks.step4Title': 'Retener: que se quede',
  'howItWorks.step4Body': 'Los conceptos vuelven para repaso en el momento adecuado, para que lo aprendido siga ahí semanas después, no solo ese día.',
  'howItWorks.ctaPrimary': 'Empieza a aprender con StudyUS',
  'onboarding.title': 'Primeros pasos',
  'onboarding.dismiss': 'Ocultar',
  'onboarding.step1Title': 'Crea tu primera materia',
  'onboarding.step1Body': 'Agrupa lo que estás estudiando — una asignatura o un curso — para empezar.',
  'onboarding.step1Cta': 'Crear materia',
  'onboarding.step2Title': 'Agrega contenido',
  'onboarding.step2Body': 'Sube un PDF o escribe un concepto — StudyUS lo organiza automáticamente.',
  'onboarding.step2Cta': 'Agregar contenido',
  'onboarding.step3Title': 'Haz tu primera práctica',
  'onboarding.step3Body': 'Responde un quiz corto para que StudyUS empiece a medir tu dominio.',
