  'marketing.seoTitle': 'StudyUS | Lernen, beweisen, behalten',
  'marketing.seoDescription': 'StudyUS ist ein adaptives Lernsystem: Es hilft dir, ein Konzept zu verstehen, zu üben, es selbstständig zu beweisen, zu behalten und in neuen Situationen anzuwenden.',
  'marketing.h1': 'Richtig antworten reicht nicht. Beherrsche es.',
  'marketing.subhead': 'StudyUS ist ein adaptives Lernsystem. Es ermittelt, was du brauchst, führt dich durchs Lernen und prüft, ob du es wirklich kannst -- allein, später und in neuen Situationen.',
  'marketing.navHowItWorks': 'So funktioniert es',
  'marketing.footerTagline': 'Lernen. Beweisen. Behalten.',
  'marketing.section1Title': 'Es entscheidet, was du brauchst',
  'marketing.section1Body': 'StudyUS liest dein Material, zerlegt es in Konzepte und sagt dir, was als Nächstes dran ist -- du musst dein Lernen nie selbst planen.',
  'marketing.section2Title': 'Es hört bei der richtigen Antwort nicht auf',
  'marketing.section2Body': 'Eine richtige Antwort ist der Anfang. Danach prüft StudyUS, ob du es ohne Hilfe kannst, es später noch weißt und es woanders anwenden kannst.',
  'marketing.section3Title': 'Es zeigt dir, wo du wirklich stehst',
  'marketing.section3Body': 'Für jedes Konzept siehst du, was verstanden, selbstständig bewiesen, behalten ist und was noch fehlt -- auf Basis echter Nachweise, nicht einer Note.',
  'marketing.section4Title': 'Es passt sich dir an',
  'marketing.section4Body': 'Was du übst, wann ein Konzept zur Wiederholung zurückkommt und was StudyUS als Nächstes fragt, richtet sich nach deiner echten Leistung -- kein fester Kurs für alle gleich.',
  'marketing.section5Title': 'Für die echte Schule gemacht',
  'marketing.section5Body': 'Verfolge deinen Lernfortschritt über die Zeit und geh vorbereitet in Prüfungen -- auch IB-Prüfungen für Diploma- und MYP-Schüler.',
  'marketing.ctaPrimary': 'Kostenlos starten',
  'marketing.ctaSecondary': 'So funktioniert es',
  'marketing.faqTitle': 'Häufig gestellte Fragen',
  'marketing.faq1Q': 'Ist StudyUS ein KI-Chatbot?',
  'marketing.faq1A': 'Nein. StudyUS ist ein strukturiertes Lernsystem -- es entscheidet, was du brauchst, führt durchs Lernen und prüft, ob du es wirklich kannst. Es ist kein Chatfenster für Fragen.',
  'marketing.faq2Q': 'Sind das nur Karteikarten oder Quizze?',
  'marketing.faq2A': 'Nein. Karteikarten prüfen das Abrufen einzelner Fakten. StudyUS baut Verständnis für ein Konzept auf und prüft dann, ob du es selbstständig kannst, es später behältst und in einer neuen Situation anwendest.',
  'marketing.faq3Q': 'Erstellt es nur einen Lernplan?',
  'marketing.faq3A': 'Nein. Ein Plan sagt dir, wann du lernst. StudyUS entscheidet, was du lernst, vermittelt die Konzepte und misst, ob du dich wirklich verbesserst.',
  'howItWorks.seoTitle': 'So funktioniert StudyUS | Lernen, üben, beweisen, behalten, übertragen',
  'howItWorks.seoDescription': 'Der StudyUS-Lernzyklus: ein Konzept verstehen, üben, selbstständig beweisen, über die Zeit behalten und auf neue Situationen übertragen.',
  'howItWorks.h1': 'Lernen. Üben. Beweisen. Behalten. Übertragen.',
  'howItWorks.intro': 'StudyUS ist keine Karteikarten-App und kein Chatbot. Es ist ein Lernzyklus, der sicherstellt, dass du jedes Konzept wirklich verstehst und anwenden kannst -- nicht nur wiedererkennst.',
  'howItWorks.step1Title': 'Lernen: ein klares mentales Modell aufbauen',
  'howItWorks.step1Body': 'Jedes Konzept wird klar und mit echten Beispielen erklärt, damit du die Idee selbst verstehst -- keinen Merk-Trick.',
  'howItWorks.step2Title': 'Üben: damit arbeiten, mit Hilfe',
  'howItWorks.step2Body': 'Du wendest das Konzept in geführter Übung an, mit verfügbaren Hinweisen, bis es vertraut ist.',
  'howItWorks.step3Title': 'Beweisen: allein schaffen',
  'howItWorks.step3Body': 'StudyUS prüft, ob du es selbstständig kannst -- ohne Hinweise -- bevor das Konzept als deins zählt.',
  'howItWorks.step4Title': 'Behalten: verankern',
  'howItWorks.step4Body': 'Konzepte kommen zur richtigen Zeit zur Wiederholung zurück, damit Gelerntes auch Wochen später noch da ist, nicht nur am Tag selbst.',
  'howItWorks.ctaPrimary': 'Mit StudyUS zu lernen beginnen',
  'onboarding.title': 'Erste Schritte',
  'onboarding.dismiss': 'Ausblenden',
  'onboarding.step1Title': 'Erstelle dein erstes Fach',
  'onboarding.step1Body': 'Fasse zusammen, was du gerade lernst — ein Fach oder einen Kurs —, um loszulegen.',
  'onboarding.step1Cta': 'Fach erstellen',
  'onboarding.step2Title': 'Inhalte hinzufügen',
  'onboarding.step2Body': 'Lade ein PDF hoch oder schreibe ein Konzept — StudyUS ordnet es automatisch ein.',
  'onboarding.step2Cta': 'Inhalt hinzufügen',
  'onboarding.step3Title': 'Deine erste Übung machen',
  'onboarding.step3Body': 'Beantworte ein kurzes Quiz, damit StudyUS beginnt, dein Verständnis zu messen.',
