  'home.tagline': "Votre système d'exploitation d'apprentissage adaptatif.",
  'home.signIn': 'Se connecter',
  'home.signUp': 'Créer un compte',
  'marketing.seoTitle': 'StudyUS | Apprends-le, prouve-le, garde-le',
  'marketing.seoDescription': 'StudyUS est un système d\'apprentissage adaptatif : il t\'aide à comprendre un concept, à t\'entraîner, à prouver que tu sais le faire seul, à le retenir et à l\'appliquer dans des situations nouvelles.',
  'marketing.h1': 'Avoir juste ne suffit pas. Maîtrise-le.',
  'marketing.subhead': 'StudyUS est un système d\'apprentissage adaptatif. Il détermine ce dont tu as besoin, te guide pour l\'apprendre et vérifie que tu sais vraiment le faire -- seul, plus tard, et dans des situations nouvelles.',
  'marketing.navHowItWorks': 'Comment ça marche',
  'marketing.footerTagline': 'Apprends-le. Prouve-le. Garde-le.',
  'marketing.section1Title': 'Il décide de ce dont tu as besoin',
  'marketing.section1Body': 'StudyUS lit ton contenu, le découpe en concepts et te dit quoi travailler ensuite -- tu n\'as jamais à planifier ton étude.',
  'marketing.section2Title': 'Il ne s\'arrête pas à une bonne réponse',
  'marketing.section2Body': 'Une bonne réponse est un début. StudyUS vérifie ensuite que tu sais le faire sans aide, que tu t\'en souviens plus tard et que tu l\'utilises ailleurs.',
  'marketing.section3Title': 'Il te montre où tu en es vraiment',
  'marketing.section3Body': 'Pour chaque concept, tu vois ce qui est compris, prouvé seul, retenu et ce qui reste à travailler -- sur des preuves réelles, pas une note.',
  'marketing.section4Title': 'Il s\'adapte à toi',
  'marketing.section4Body': 'Ce que tu travailles, quand un concept revient en révision et ce que StudyUS demande ensuite suivent tes résultats réels -- pas un cours figé identique pour tous.',
  'marketing.section5Title': 'Pensé pour l\'école réelle',
  'marketing.section5Body': 'Suis ta maîtrise dans le temps et aborde les examens -- y compris les évaluations de l\'IB pour le Diplôme et le PEI -- préparé, pas seulement familier.',
  'marketing.ctaPrimary': 'Commencer gratuitement',
  'marketing.ctaSecondary': 'Voir comment ça marche',
  'marketing.faqTitle': 'Questions fréquentes',
  'marketing.faq1Q': 'StudyUS est-il un chatbot IA ?',
  'marketing.faq1A': 'Non. StudyUS est un système d\'apprentissage structuré : il décide de ce dont tu as besoin, guide l\'apprentissage et vérifie que tu sais vraiment faire. Ce n\'est pas une fenêtre de discussion.',
  'marketing.faq2Q': 'Ce ne sont que des cartes ou des quiz ?',
  'marketing.faq2A': 'Non. Les cartes testent le rappel de faits isolés. StudyUS construit la compréhension d\'un concept, puis vérifie que tu sais le faire seul, t\'en souvenir plus tard et l\'appliquer dans une situation nouvelle.',
  'marketing.faq3Q': 'Il fait juste un planning de révision ?',
  'marketing.faq3A': 'Non. Un planning te dit quand étudier. StudyUS décide quoi étudier, enseigne les concepts et mesure si tu progresses réellement.',
  'howItWorks.seoTitle': 'Comment fonctionne StudyUS | Apprendre, s\'entraîner, prouver, retenir, transférer',
  'howItWorks.seoDescription': 'Le cycle d\'apprentissage StudyUS : comprendre un concept, s\'entraîner, prouver qu\'on sait le faire seul, le retenir dans le temps et le transférer à des situations nouvelles.',
  'howItWorks.h1': 'Apprendre. S\'entraîner. Prouver. Retenir. Transférer.',
  'howItWorks.intro': 'StudyUS n\'est ni une appli de cartes ni un chatbot. C\'est un cycle d\'apprentissage qui s\'assure que tu comprends vraiment chaque concept et sais l\'utiliser -- pas seulement le reconnaître.',
  'howItWorks.step1Title': 'Apprendre : se construire un modèle mental clair',
  'howItWorks.step1Body': 'Chaque concept est expliqué clairement, avec de vrais exemples, pour que tu comprennes l\'idée elle-même -- pas un raccourci pour la mémoriser.',
  'howItWorks.step2Title': 'S\'entraîner : travailler avec, avec de l\'aide',
  'howItWorks.step2Body': 'Tu appliques le concept en pratique guidée, avec des indices disponibles, jusqu\'à ce qu\'il devienne familier.',
  'howItWorks.step3Title': 'Prouver : y arriver seul',
  'howItWorks.step3Body': 'StudyUS vérifie que tu sais le faire seul -- sans indices -- avant de compter le concept comme acquis.',
  'howItWorks.step4Title': 'Retenir : ancrer',
  'howItWorks.step4Body': 'Les concepts reviennent en révision au bon moment, pour que ce que tu as appris soit encore là des semaines plus tard, pas seulement le jour même.',
  'howItWorks.ctaPrimary': 'Commencer à apprendre avec StudyUS',
  'onboarding.title': 'Premiers pas',
  'onboarding.dismiss': 'Masquer',
  'onboarding.step1Title': 'Crée ta première matière',
  'onboarding.step1Body': "Regroupe ce que tu étudies — une matière ou un cours — pour commencer.",
