  'onboarding.step2Title': 'Ajoute du contenu',
  'onboarding.step2Body': 'Importe un PDF ou écris un concept — StudyUS l\'organise automatiquement.',
  'onboarding.step2Cta': 'Ajouter du contenu',
  'onboarding.step3Title': 'Fais ton premier entraînement',
  'onboarding.step3Body': 'Réponds à un court quiz pour que StudyUS commence à mesurer ta maîtrise.',
