  'home.tagline': 'Seu sistema operacional de aprendizagem adaptativo.',
  'home.signIn': 'Entrar',
  'home.signUp': 'Criar conta',
  'marketing.seoTitle': 'StudyUS | Aprenda, prove, mantenha',
  'marketing.seoDescription': 'O StudyUS é um sistema de aprendizagem adaptativo: ajuda você a entender um conceito, praticá-lo, provar que consegue fazer sozinho, retê-lo e aplicá-lo em situações novas.',
  'marketing.h1': 'Acertar não basta. Domine.',
  'marketing.subhead': 'O StudyUS é um sistema de aprendizagem adaptativo. Descobre o que você precisa, guia você no aprendizado e verifica que você realmente sabe fazer -- sozinho, depois e em situações novas.',
  'marketing.navHowItWorks': 'Como funciona',
  'marketing.footerTagline': 'Aprenda. Prove. Mantenha.',
  'marketing.section1Title': 'Ele decide o que você precisa',
  'marketing.section1Body': 'O StudyUS lê seu material, divide em conceitos e diz o que trabalhar a seguir -- você nunca precisa planejar seu próprio estudo.',
  'marketing.section2Title': 'Não para numa resposta certa',
  'marketing.section2Body': 'Acertar é o começo. Depois o StudyUS verifica que você consegue fazer sem ajuda, ainda lembra mais tarde e usa em algo novo.',
  'marketing.section3Title': 'Mostra onde você está de verdade',
  'marketing.section3Body': 'Em cada conceito você vê o que foi entendido, provado sozinho, retido e o que falta -- com evidência real, não uma nota.',
  'marketing.section4Title': 'Ele se adapta a você',
  'marketing.section4Body': 'O que você pratica, quando um conceito volta para revisão e o que o StudyUS pede a seguir seguem seu desempenho real -- não um curso fixo igual para todos.',
  'marketing.section5Title': 'Feito para a escola real',
  'marketing.section5Body': 'Acompanhe seu domínio ao longo do tempo e chegue às provas -- incluindo avaliações do IB para Diploma e MYP -- preparado, não apenas familiarizado.',
  'marketing.ctaPrimary': 'Comece de graça',
  'marketing.ctaSecondary': 'Veja como funciona',
  'marketing.faqTitle': 'Perguntas frequentes',
  'marketing.faq1Q': 'O StudyUS é um chatbot de IA?',
  'marketing.faq1A': 'Não. O StudyUS é um sistema de aprendizagem estruturado -- decide o que você precisa, guia o aprendizado e verifica que você realmente consegue. Não é uma janela de conversa para fazer perguntas.',
  'marketing.faq2Q': 'São só cartões ou questionários?',
  'marketing.faq2A': 'Não. Cartões testam a lembrança de fatos isolados. O StudyUS constrói a compreensão de um conceito e depois verifica que você consegue fazer sozinho, lembrar depois e aplicar numa situação nova.',
  'marketing.faq3Q': 'Ele só monta um cronograma de estudo?',
  'marketing.faq3A': 'Não. Um cronograma diz quando estudar. O StudyUS decide o que estudar, ensina os conceitos e acompanha se você está realmente melhorando.',
  'howItWorks.seoTitle': 'Como o StudyUS funciona | Aprender, praticar, provar, reter, transferir',
  'howItWorks.seoDescription': 'O ciclo de aprendizagem do StudyUS: entender um conceito, praticá-lo, provar que consegue fazer sozinho, retê-lo ao longo do tempo e transferi-lo para situações novas.',
  'howItWorks.h1': 'Aprender. Praticar. Provar. Reter. Transferir.',
  'howItWorks.intro': 'O StudyUS não é um app de cartões nem um chatbot. É um ciclo de aprendizagem que garante que você realmente entende cada conceito e sabe usá-lo -- não apenas reconhecê-lo.',
  'howItWorks.step1Title': 'Aprender: construir um modelo mental claro',
  'howItWorks.step1Body': 'Cada conceito é explicado com clareza, com exemplos reais, para você entender a ideia em si -- não um atalho para memorizar.',
  'howItWorks.step2Title': 'Praticar: trabalhar com ele, com ajuda',
  'howItWorks.step2Body': 'Você aplica o conceito em prática guiada, com dicas disponíveis, até ele ficar familiar.',
  'howItWorks.step3Title': 'Provar: conseguir sozinho',
  'howItWorks.step3Body': 'O StudyUS verifica que você consegue fazer sozinho -- sem dicas -- antes de considerar o conceito seu.',
  'howItWorks.step4Title': 'Reter: fixar',
  'howItWorks.step4Body': 'Os conceitos voltam para revisão na hora certa, para que o que você aprendeu ainda esteja lá semanas depois, não só no dia.',
  'howItWorks.ctaPrimary': 'Comece a aprender com o StudyUS',
  'onboarding.title': 'Primeiros passos',
  'onboarding.dismiss': 'Ocultar',
  'onboarding.step1Title': 'Crie sua primeira matéria',
  'onboarding.step1Body': 'Agrupe o que você está estudando — uma disciplina ou um curso — para começar.',
  'onboarding.step1Cta': 'Criar matéria',
  'onboarding.step2Title': 'Adicione conteúdo',
  'onboarding.step2Body': 'Envie um PDF ou escreva um conceito — o StudyUS organiza tudo automaticamente.',
  'onboarding.step2Cta': 'Adicionar conteúdo',
  'onboarding.step3Title': 'Faça sua primeira prática',
  'onboarding.step3Body': 'Responda a um quiz curto para o StudyUS começar a medir seu domínio.',
